From d89bc31854d4f3d1c686e4e763f35626dee7e2f1 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:47:46 +0100
Subject: [PATCH] libkmpris: make media keys follow the player chosen in the
 widget

kded picked the target of the global media shortcuts on its own, so the
keys could control another player than the one chosen in the widget. The
widget now tells kded its choice, kept until changed or the app quits.

BUG: 460771
---
 libkmpris/kded/mprisservice.cpp |  5 +++++
 libkmpris/kded/mprisservice.h   |  7 +++++++
 libkmpris/mpris2model.cpp       | 12 ++++++++++++
 libkmpris/multiplexer.cpp       | 21 +++++++++++++++++++--
 libkmpris/multiplexer.h         |  7 +++++++
 5 files changed, 50 insertions(+), 2 deletions(-)

diff --git a/libkmpris/kded/mprisservice.cpp b/libkmpris/kded/mprisservice.cpp
index 32a7593811..41a11b0c3a 100644
--- a/libkmpris/kded/mprisservice.cpp
+++ b/libkmpris/kded/mprisservice.cpp
@@ -31,6 +31,11 @@ MprisService::MprisService(QObject *parent, const QList<QVariant> &)

 MprisService::~MprisService() = default;

+void MprisService::setActivePlayer(const QString &dbusAddress)
+{
+    m_multiplexer->setActivePlayer(dbusAddress);
+}
+
 void MprisService::onPlayPause()
 {
     if (!m_activePlayer) {
diff --git a/libkmpris/kded/mprisservice.h b/libkmpris/kded/mprisservice.h
index 7da53b640b..14a6a9d773 100644
--- a/libkmpris/kded/mprisservice.h
+++ b/libkmpris/kded/mprisservice.h
@@ -20,11 +20,18 @@ class KActionCollection;
 class MprisService : public KDEDModule
 {
     Q_OBJECT
+    Q_CLASSINFO("D-Bus Interface", "org.kde.plasma.mprisservice")

 public:
     explicit MprisService(QObject *parent, const QList<QVariant> &);
     ~MprisService() override;

+    /**
+     * Makes the player chosen in a Media Player widget the target of the global shortcuts,
+     * or goes back to the automatically chosen player when the address is empty
+     */
+    Q_SCRIPTABLE void setActivePlayer(const QString &dbusAddress);
+
 private Q_SLOTS:
     void onPlayPause();
     void onNext();
diff --git a/libkmpris/mpris2model.cpp b/libkmpris/mpris2model.cpp
index 98ee626bc6..2ac83ff4e9 100644
--- a/libkmpris/mpris2model.cpp
+++ b/libkmpris/mpris2model.cpp
@@ -6,6 +6,8 @@

 #include "mpris2model.h"

+#include <QDBusConnection>
+#include <QDBusMessage>
 #include <QUrl>

 #include "mpris2filterproxymodel.h"
@@ -59,6 +61,16 @@ void Mpris2Model::setCurrentIndex(unsigned _index)
     }
     Q_EMIT currentPlayerChanged();
     Q_EMIT currentIndexChanged();
+
+    // Let the global media shortcuts follow the player chosen here
+    if (m_currentPlayer) {
+        QDBusMessage msg = QDBusMessage::createMethodCall(QStringLiteral("org.kde.kded6"),
+                                                          QStringLiteral("/modules/mprisservice"),
+                                                          QStringLiteral("org.kde.plasma.mprisservice"),
+                                                          QStringLiteral("setActivePlayer"));
+        msg << (index(m_currentIndex, 0).data(Mpris2SourceModel::IsMultiplexerRole).toBool() ? QString() : m_currentPlayer->dbusAddress());
+        QDBusConnection::sessionBus().call(msg, QDBus::NoBlock);
+    }
 }

 PlayerContainer *Mpris2Model::currentPlayer() const
diff --git a/libkmpris/multiplexer.cpp b/libkmpris/multiplexer.cpp
index 3d7a4b0a9f..1a30201ae9 100644
--- a/libkmpris/multiplexer.cpp
+++ b/libkmpris/multiplexer.cpp
@@ -52,12 +52,28 @@ QBindable<PlayerContainer *> Multiplexer::activePlayer() const
     return &m_activePlayer;
 }

+void Multiplexer::setActivePlayer(const QString &dbusAddress)
+{
+    m_userSelected = false;
+    for (int i = 0, size = m_filterModel->rowCount(); i < size; ++i) {
+        auto *const container = m_filterModel->index(i, 0).data(Mpris2SourceModel::ContainerRole).value<PlayerContainer *>();
+        if (container->dbusAddress() == dbusAddress) {
+            m_activePlayer = container;
+            m_activePlayerIndex = i;
+            m_userSelected = true;
+            return;
+        }
+    }
+    evaluatePlayers();
+}
+
 void Multiplexer::onRowsInserted(const QModelIndex &, int first, int)
 {
     auto *const container = m_filterModel->index(first, 0).data(Mpris2SourceModel::ContainerRole).value<PlayerContainer *>();
     connect(container, &PlayerContainer::playbackStatusChanged, this, &Multiplexer::onPlaybackStatusChanged);

-    if (!m_activePlayer || (m_activePlayer->playbackStatus() != PlaybackStatus::Playing && container->playbackStatus() == PlaybackStatus::Playing)) {
+    if (!m_activePlayer
+        || (!m_userSelected && m_activePlayer->playbackStatus() != PlaybackStatus::Playing && container->playbackStatus() == PlaybackStatus::Playing)) {
         m_activePlayer = container;
         m_activePlayerIndex = first;
     } else {
@@ -78,6 +94,7 @@ void Multiplexer::onRowsAboutToBeRemoved(const QModelIndex &, int first, int)
                    qUtf8Printable(QStringLiteral("Active player %1 does not match active index %2 (%3)")
                                       .arg(m_activePlayer->identity(), QString::number(m_activePlayerIndex.value()), container->identity())));
         m_activePlayer = nullptr;
+        m_userSelected = false;
         // Index is updated in evaluatePlayers() later
     }
 }
@@ -95,7 +112,7 @@ void Multiplexer::onRowsRemoved(const QModelIndex &, int, int)
 void Multiplexer::onPlaybackStatusChanged()
 {
     // m_activePlayer can't be nullptr here, otherwise something is wrong
-    if (m_activePlayer->playbackStatus() == PlaybackStatus::Playing) {
+    if (m_userSelected || m_activePlayer->playbackStatus() == PlaybackStatus::Playing) {
         // Keep the current player
         return;
     }
diff --git a/libkmpris/multiplexer.h b/libkmpris/multiplexer.h
index ec1f2bb569..2d6bca4036 100644
--- a/libkmpris/multiplexer.h
+++ b/libkmpris/multiplexer.h
@@ -32,6 +32,12 @@ public:
     QBindable<int> activePlayerIndex() const;
     QBindable<PlayerContainer *> activePlayer() const;

+    /**
+     * Keeps the player chosen by the user as the active player until it's gone.
+     * An empty address goes back to choosing the player automatically.
+     */
+    void setActivePlayer(const QString &dbusAddress);
+
 Q_SIGNALS:
     void activePlayerIndexChanged(int newIndex);

@@ -46,6 +52,7 @@ private:
     void evaluatePlayers();

     std::shared_ptr<Mpris2FilterProxyModel> m_filterModel;
+    bool m_userSelected = false;
     Q_OBJECT_BINDABLE_PROPERTY_WITH_ARGS(Multiplexer, PlayerContainer *, m_activePlayer, nullptr)
     Q_OBJECT_BINDABLE_PROPERTY_WITH_ARGS(Multiplexer, int, m_activePlayerIndex, -1, &Multiplexer::activePlayerIndexChanged)
 };
